mapper.select:
SELECT DISTINCT activity_id
FROM activity_session
WHERE activity_id IN
#{id}
  AND status = 'OPEN'
  AND (remaining_seats IS NULL OR remaining_seats > 0)

  AND start_at < DATE_ADD(#{dateEnd}, INTERVAL 1 DAY)
  AND end_at >= #{dateStart}


  AND TIME(start_at) < #{timeEnd}
  AND TIME(end_at) > #{timeStart}
